export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const fmt=(n,d=2)=>Number.isFinite(n)?Number(n.toFixed(d)).toLocaleString('en-GB',{maximumFractionDigits:d}):'—';
export const chemText=s=>esc(s).replace(/([A-Za-z\)])(\d+)/g,'$1<sub>$2</sub>');
export function icon(name){const paths={heat:'M8 3c-4 5 4 6 0 11m5-11c-4 5 4 6 0 11m5-11c-4 5 4 6 0 11M4 20h16',transfer:'M3 8h17m-4-4 4 4-4 4M21 16H4m4-4-4 4 4 4',filter:'M3 4h18l-7 9v6l-4 2v-8z',crystallise:'M12 2 3 8l4 12h10l4-12-9-6zM3 8h18M7 20l5-18 5 18',evaporate:'M4 14h16l-3 7H7zM7 10c-3-3 3-4 0-7m5 7c-3-3 3-4 0-7m5 7c-3-3 3-4 0-7','gas-test':'M6 13a7 7 0 1 0 12-7M7 3v6H1m12 3h.01',history:'M4 8a9 9 0 1 1-1 8M4 3v5h5m3-2v6l4 2',undo:'M8 5 3 10l5 5M3 10h10a7 7 0 0 1 7 7',bench:'M9 3h6m-5 0v6L4 19q-1 2 2 2h12q3 0 2-2L14 9V3M7 15h10',practicals:'M4 4h16v16H4zM8 8h3m3 0h3M8 12h3m3 0h3M8 16h3m3 0h3',learn:'M3 5q5-2 9 1 4-3 9-1v14q-5-2-9 1-4-3-9-1zM12 6v14',periodic:'M3 3h5v5H3zM16 3h5v5h-5zM3 11h5v5H3zM10 11h5v5h-5zM17 11h5v5h-5zM3 19h19',tools:'M5 3h14v18H5zM8 7h8M8 12h1m3 0h1m3 0h1M8 16h1m3 0h1m3 0h1',notebook:'M6 3h14v18H6zM3 7h5M3 12h5M3 17h5M11 8h5M11 12h5'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.bench}"/></svg>`;}
let count=0;
export function glassware(shape='beaker',color='#69b7dc',fill=.45,solid='#eee',hasSolid=false,bubbles=false,heated=false){
 const id='glass-'+(++count),level=153-Math.max(0,Math.min(1,fill))*(shape==='dish'?48:116);
 const paths={beaker:'M28 26H116L110 36V145Q110 158 97 158H43Q30 158 30 145V37L24 26Z',flask:'M57 16H83V60L116 141Q122 158 104 158H36Q18 158 24 141L57 60Z',tube:'M48 18H92V136Q92 158 70 158Q48 158 48 136Z',dish:'M20 99H120L110 145Q108 156 96 156H44Q32 156 30 145Z'};
 const path=paths[shape]||paths.beaker;
 const shine={beaker:'M36 43V137Q36 148 42 149',flask:'M62 23V63L33 139Q29 150 40 150',tube:'M54 26V134Q54 149 64 151',dish:'M28 106L37 139Q40 149 48 149'}[shape]||'M36 43V137';
 return `<svg viewBox="0 0 140 185" role="img" aria-label="${esc(shape)}${hasSolid?' with solid':''}${bubbles?', gas produced':''}"><defs><linearGradient id="${id}-g"><stop stop-color="#ffffffa0"/><stop offset=".22" stop-color="#ffffff20"/><stop offset=".65" stop-color="#ffffff05"/><stop offset="1" stop-color="#ffffff90"/></linearGradient><linearGradient id="${id}-l" x2="0" y2="1"><stop stop-color="${esc(color)}" stop-opacity=".55"/><stop offset="1" stop-color="${esc(color)}" stop-opacity=".9"/></linearGradient><clipPath id="${id}"><path d="${path}"/></clipPath></defs><ellipse cx="70" cy="165" rx="48" ry="5" fill="#5f859c" opacity=".13"/><g clip-path="url(#${id})"><rect x="18" y="${level}" width="110" height="160" fill="url(#${id}-l)" opacity="${fill>0?1:0}"/><ellipse cx="70" cy="${level}" rx="52" ry="4" fill="${esc(color)}" opacity="${fill>0?.5:0}"/>${hasSolid?Array.from({length:9},(_,i)=>`<path d="M${33+i*7} ${148-i%3*4}l5 -5 6 4 -3 7 -7 -1Z" fill="${esc(solid)}" stroke="#6b859030"/>`).join(''):''}${bubbles?Array.from({length:7},(_,i)=>`<circle class="bubble" cx="${43+(i*17)%55}" cy="${148-i%2*12}" r="${2+i%3}" fill="#fff" opacity=".7" style="animation-delay:${-i*.3}s"/>`).join(''):''}</g><path d="${path}" fill="url(#${id}-g)" stroke="#8ba4b9" stroke-opacity=".7" stroke-width="1.4"/><path d="${shine}" clip-path="url(#${id})" stroke="white" opacity=".7" fill="none" stroke-width="3" stroke-linecap="round"/>${shape==='beaker'?Array.from({length:5},(_,i)=>`<path d="M88 ${153-(200-i*40)/250*116}h15" stroke="#7c9bb3" stroke-width="1" opacity=".5"/><text x="74" y="${156-(200-i*40)/250*116}" font-size="6" fill="#7a97b0">${200-i*40}</text>`).join(''):''}${heated?'<g stroke="#9bbbd0" fill="none" opacity=".55"><path class="steam" d="M52 9q-9-12 0-24"/><path class="steam" d="M73 9q-9-12 0-24" style="animation-delay:-1s"/></g>':''}</svg>`;
}
export function chart(points,{xLabel='Time / s',yLabel='Gas volume / mL',compare=null,marker=null}={}){
 const W=560,H=240,L=55,R=20,T=20,B=45,all=[...points,...(compare||[])];let xmax=Math.max(1,...all.map(p=>p[0])),ymax=Math.max(1,...all.map(p=>p[1]));
 const sx=x=>L+x/xmax*(W-L-R),sy=y=>H-B-y/ymax*(H-T-B),line=pts=>pts.map((p,i)=>(i?'L':'M')+sx(p[0]).toFixed(2)+','+sy(p[1]).toFixed(2)).join(' ');
 return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(yLabel)} against ${esc(xLabel)}">${Array.from({length:5},(_,i)=>{const y=i*ymax/4;return `<line class="grid" x1="${L}" x2="${W-R}" y1="${sy(y)}" y2="${sy(y)}"/><text x="${L-9}" y="${sy(y)+3}" text-anchor="end">${fmt(y,1)}</text><text x="${sx(i*xmax/4)}" y="${H-B+18}" text-anchor="middle">${fmt(i*xmax/4,1)}</text>`;}).join('')}<path class="axis" d="M${L} ${T}V${H-B}H${W-R}"/><path class="curve" d="${line(points)}"/>${compare?`<path class="compare" d="${line(compare)}"/>`:''}${marker?`<circle cx="${sx(marker[0])}" cy="${sy(marker[1])}" r="4" fill="#557ece" stroke="white" stroke-width="2"/>`:''}<text x="${W/2}" y="${H-7}" text-anchor="middle">${esc(xLabel)}</text><text transform="translate(13 ${H/2}) rotate(-90)" text-anchor="middle">${esc(yLabel)}</text></svg>`;
}
export function date(s){return new Date(s).toLocaleString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});}
